function Steering__force()
    clc; clear; close all;

    % =========================================================================
    % 1. FIX BEMENETI PARAMÉTEREK (ÚJ ÁTTÉTEL-DEFINÍCIÓVAL)
    % =========================================================================
    F_pilot_max = 410;          % Pilóta által kifejthető max. kényelmes erő [N]
    D_steering_wheel = 280;     % Kormánykerék átmérője [mm]
    
    % ÚJ BEMENET: Kormánymű áttétel [fogasléc elmozdulás / kormánykerék fordulat]
    % Egység: mm / fordulat (mm/rev)
    rack_displ_per_rev = 60; 
    
    % =========================================================================
    % 2. MECHANIKAI ÁTSZÁMÍTÁS (DIPLOMA-ALAPÚ LEVEZETÉS)
    % =========================================================================
    R_sw = D_steering_wheel / 2; % Kormánykerék sugara [mm]
    
    % Az effektív fogaskerék (pinion) sugár kiszámítása a mm/rev áttételből
    % 1 fordulat = 2 * pi radián
    r_pinion = rack_displ_per_rev / (2 * pi); % [mm]

    % =========================================================================
