    % ALFA SZÖG VEKTOR [fok] (A kormányösszekötő és a kormánykar szöge)
    % Egyenesmenetben ideális (0°), végállásban eléri a kinematikai veszteséget (25°)
    alpha_vector = linspace(-30, 15, 311); 

% =========================================================================
    % 4. VEKTORIZÁLT SZÁMÍTÁSOK
    % =========================================================================
    F_tie_rod_avail = (F_pilot_max * R_sw) / r_pinion;
    max(F_tie_rod_avail);
    
    % Element-by-element számítás
    L_required_vector = (Mz_vector .* 1000) ./ (F_tie_rod_avail .* cosd(alpha_vector)); 
    
    % JAVÍTÁS: A (:) kényszeríti, hogy egyetlen skalár számot kapjunk, 
    % az 'omitnan' pedig kiszűri a kerekítési hibákból eredő esetleges NaN értékeket.
    L_design = max(L_required_vector(:), [], 'omitnan'); 

    % Vissza-ellenőrzés a valós erőkkel
    F_tie_rod_actual = (Mz_vector .* 1000) ./ (L_design .* cosd(alpha_vector)); 
    max(F_tie_rod_actual);
    F_pilot_actual = (F_tie_rod_actual .* r_pinion) ./ R_sw; 

    % =========================================================================
    % 5. DIAGRAMOK PLOTOLÁSA (Minden tengelykorlát hiba kiküszöbölve)
    % =========================================================================
    figure('Color', 'w', 'Position', [100, 100, 950, 650]);
    
    % 1. Grafikon: Bemeneti Mz nyomatékvektor
    subplot(2, 2, 1);
    plot(delta_range, Mz_vector, 'r-', 'LineWidth', 2); grid on; box on;
    title('Gumiabroncs önbeálló nyomatéka (M_z)');
    xlabel('Kerékszög (\delta) [fok]'); ylabel('Nyomaték [Nm]');
    
    % 2. Grafikon: Kormányáttétel
    subplot(2, 2, 2);
    plot([0; max(delta_range(:))], [rack_displ_per_rev; rack_displ_per_rev], 'g-', 'LineWidth', 2); grid on; box on;
    title('Kormánymű áttételi tényező');
    xlabel('Kerékszög (\delta) [fok]'); ylabel('Áttétel [mm/rev]');
    ylim([0 rack_displ_per_rev + 20]);
    text(2, rack_displ_per_rev + 8, sprintf('C_{rack} = %.1f mm/rev\n(r_{pinion} = %.2f mm)', rack_displ_per_rev, r_pinion), 'FontWeight', 'bold');
    
    % 3. Grafikon: Szükséges karhossz (A JAVÍTOTT GRAFIKON)
    subplot(2, 2, 3);
    plot(delta_range, L_required_vector, 'b-', 'LineWidth', 2); hold on; 
    
    % Vízszintes tervezési vonal rajzolása
    plot([min(delta_range(:)); max(delta_range(:))], [L_design; L_design], 'r--', 'LineWidth', 1.5); 
    
    grid on; box on;
    title('Szükséges vs. Tervezett Karhossz');
    xlabel('Kerékszög (\delta) [fok]'); ylabel('Kormánykar hossz [mm]');
    xlim([0 max(delta_range(:))]); 
    
    % JAVÍTÁS: Dinamikus, de szigorúan 2 elemű határ Ellenőrzés
    ylim_max = max(L_required_vector(:), [], 'omitnan');
    if isfinite(ylim_max) && ylim_max > 0
        ylim([0 ylim_max + 30]);
    else
        ylim auto; % Ha teljesen hibás az adatstruktúra, a MATLAB-ra bízzuk a skálázást crash helyett
    end
    % legend('Szükséges pontonként', ['Beépített fix méret: ' num2str(round(L_design,1)) ' mm'], 'Location', 'SouthEast');
    
    % 4. Grafikon: Valóságos pilóta erő
    subplot(2, 2, 4);
    plot(delta_range, F_pilot_actual, 'k-', 'LineWidth', 2); hold on;
    plot([min(delta_range(:)); max(delta_range(:))], [F_pilot_max; F_pilot_max], 'r:', 'LineWidth', 1.5);
    grid on; box on;
    title('Pilóta fizikai terhelése a kanyarban');
    xlabel('Kerékszög (\delta) [fok]'); ylabel('Pilóta kézi erő [N]');
    xlim([0 max(delta_range(:))]); 
    ylim([0 F_pilot_max + 20]);
    % legend('Aktuális erőigény', 'Ergonómiai korlát', 'Location', 'SouthEast');
